export const COMIC_SCENES=[{"id":"comic-fr-1","code":"HF-44-S1","title":"44th Period","from":1,"to":3,"lines":[["Laissez-moi récapituler une dernière fois avant que la cloche ne sonne.","Déjenme resumirlo una última vez antes de que suene la campana.","L01-01 - HF44S10101 - Laissez-moi récapituler une dernière fois avant que la cloche ne sonne.m4a",""],["Je vais juste revoir les points principaux vu qu'on n'a pas beaucoup de temps.","Solo voy a repasar los puntos principales, porque no tenemos mucho tiempo.","L01-02 - HF44S10102 - Je vais juste revoir les points principaux vu qu'on n'a pas beaucoup de temps.m4a",""],["Ne prenez aucun risque.","No corran ningún riesgo.","L01-03 - HF44S10103 - Ne prenez aucun risque.m4a",""],["Si quelque chose vous paraît louche, fuyez.","Si algo les parece sospechoso, huyan.","L01-04 - HF44S10104 - Si quelque chose vous paraît louche fuyez.m4a",""],["On trouvera la solution ensemble après.","Después encontraremos juntos la solución.","L01-05 - HF44S10105 - On trouvera la solution ensemble après.m4a",""],["Hé, attention !","¡Oye, cuidado!","L02-01 - HF44S10201 - Hé attention.m4a",""],["Au secours !","¡Auxilio!","L02-02 - HF44S10202 - Au secours.m4a",""],["Qu'est-ce qui se passe ?","¿Qué está pasando?","L02-03 - HF44S10203 - Qu'est-ce qui se passe.m4a",""],["Tout le monde va bien ?","¿Todos están bien?","L02-04 - HF44S10204 - Tout le monde va bien.m4a",""],["Personne n'est blessé ?","¿Nadie está herido?","L02-05 - HF44S10205 - Personne n'est blessé.m4a",""],["Ouvre la porte arrière !","¡Abre la puerta trasera!","L03-01 - HF44S10301 - Ouvre la porte arrière.m4a",""],["Qu'est-ce qui se passe ?","¿Qué está pasando?","L03-02 - HF44S10302 - Qu'est-ce qui se passe.m4a",""],["Le monstre nous a laissés dans la classe et a disparu silencieusement.","El monstruo nos dejó en el aula y desapareció en silencio.","L03-03 - HF44S10303 - Le monstre nous a laissés dans la classe et a disparu silencieusement.m4a",""],["Notre professeur est mort.","Nuestro profesor ha muerto.","L03-04 - HF44S10304 - Notre professeur est mort.m4a",""],["Tout ce qu'on pouvait faire, c'était de pleurer derrière la porte close.","Lo único que podíamos hacer era llorar detrás de la puerta cerrada.","L03-05 - HF44S10305 - Tout ce qu'on pouvait faire c'était de pleurer derrière la porte close.m4a",""]]},{"id":"comic-fr-2","code":"HF-44-S1","title":"44th Period","from":4,"to":6,"lines":[["On peut survivre et revenir à l'extérieur ?","¿Se puede sobrevivir y regresar al exterior?","L04-01 - HF44S10401 - On peut survivre et revenir à l'extérieur.m4a",""],["Personne n'est jamais ressorti des cercles noirs.","Nadie ha vuelto a salir de los círculos negros.","L04-02 - HF44S10402 - Personne n'est jamais ressorti des cercles noirs.m4a",""],["Comment tu sais qu'on peut s'en sortir ?","¿Cómo sabes que podemos salir de esta?","L04-03 - HF44S10403 - Comment tu sais qu'on peut s'en sortir.m4a",""],["Mon oncle est un survivant non officiel.","Mi tío es un superviviente no oficial.","L04-04 - HF44S10404 - Mon oncle est un survivant non officiel.m4a",""],["Tu appelles ça une hypothèse ?","¿A eso le llamas una hipótesis?","L04-05 - HF44S10405 - Tu appelles ça une hypothèse.m4a",""],["C'est un véritable labyrinthe là-dehors.","Ahí fuera hay un auténtico laberinto.","L05-01 - HF44S10501 - C'est un véritable labyrinthe là-dehors.m4a",""],["C'est pour ça qu'il faut procéder méthodiquement.","Por eso hay que proceder metódicamente.","L05-02 - HF44S10502 - C'est pour ça qu'il faut procéder méthodiquement.m4a",""],["Il faut dessiner une carte.","Hay que dibujar un mapa.","L05-03 - HF44S10503 - Il faut dessiner une carte.m4a",""],["On sortira à chaque pause pour compléter notre carte.","Saldremos en cada descanso para completar nuestro mapa.","L05-04 - HF44S10504 - On sortira à chaque pause pour compléter notre carte.m4a",""],["On finira par avoir une carte pour sortir d'ici.","Al final tendremos un mapa para salir de aquí.","L05-05 - HF44S10505 - On finira par avoir une carte pour sortir d'ici.m4a",""],["Comment on en est arrivés là ?","¿Cómo llegamos a esto?","L06-01 - HF44S10601 - Comment on en est arrivés là.m4a",""],["Tout allait bien il y a quelques heures à peine...","Todo iba bien hace apenas unas horas...","L06-02 - HF44S10602 - Tout allait bien il y a quelques heures à peine.m4a",""],["Jeongwu a raison.","Jeongwu tiene razón.","L06-03 - HF44S10603 - Jeongwu a raison.m4a",""],["On doit se concentrer pour faire sortir tout le monde d'ici sains et saufs.","Tenemos que concentrarnos para sacar a todos de aquí sanos y salvos.","L06-04 - HF44S10604 - On doit se concentrer pour faire sortir tout le monde d'ici sains et saufs.m4a",""],["Mes parents me manquent...","Extraño a mis padres...","L06-05 - HF44S10605 - Mes parents me manquent.m4a",""]]},{"id":"comic-fr-3","code":"HF-44-S1","title":"44th Period","from":7,"to":9,"lines":[["Ne pars pas, Doyun, tout seul comme ça.","No te vayas solo así, Doyun.","L07-01 - HF44S10701 - Ne pars pas Doyun tout seul comme ça.m4a",""],["J'espère que tu vas bien, Jiwoo.","Espero que estés bien, Jiwoo.","L07-02 - HF44S10702 - J'espère que tu vas bien Jiwoo.m4a",""],["On va où d'abord ?","¿Adónde vamos primero?","L07-03 - HF44S10703 - On va où d'abord.m4a",""],["Mon instinct me disait qu'ils nous mèneraient à Jiwoo.","Mi instinto me decía que nos llevarían hasta Jiwoo.","L07-04 - HF44S10704 - Mon instinct me disait qu'ils nous mèneraient à Jiwoo.m4a",""],["Je suis sûr qu'on va les trouver.","Estoy seguro de que los encontraremos.","L07-05 - HF44S10705 - Je suis sûr qu'on va les trouver.m4a",""],["J'arrive toujours pas à croire que c'est notre lycée.","Todavía no puedo creer que este sea nuestro instituto.","L08-01 - HF44S10801 - J'arrive toujours pas à croire que c'est notre lycée.m4a",""],["Faites gaffe, vous pourriez vous tordre la cheville.","Cuidado, podrían torcerse el tobillo.","L08-02 - HF44S10802 - Faites gaffe vous pourriez vous tordre la cheville.m4a",""],["T'en fais pas pour eux.","No te preocupes por ellos.","L08-03 - HF44S10803 - T'en fais pas pour eux.m4a",""],["Suffit de garder un œil sur le chrono.","Solo hay que vigilar el cronómetro.","L08-04 - HF44S10804 - Suffit de garder un œil sur le chrono.m4a",""],["On peut toujours croiser des monstres pendant les pauses.","Siempre podemos encontrarnos con monstruos durante los descansos.","L08-05 - HF44S10805 - On peut toujours croiser des monstres pendant les pauses.m4a",""],["Une fois la source du bruit éliminée, le monstre a arrêté de nous poursuivre.","Una vez eliminada la fuente del ruido, el monstruo dejó de perseguirnos.","L09-01 - HF44S10901 - Une fois la source du bruit éliminée le monstre a arrêté de nous poursuivre.m4a",""],["T'as envie de mourir ?","¿Te quieres morir?","L09-02 - HF44S10902 - T'as envie de mourir.m4a",""],["Je... j'ai paniqué et mon esprit s'est vidé.","Yo... entré en pánico y me quedé en blanco.","L09-03 - HF44S10903 - Je j'ai paniqué et mon esprit s'est vidé.m4a",""],["Quand j'ai repris mes esprits, j'étais tout seul...","Cuando recuperé el sentido, estaba completamente solo...","L09-04 - HF44S10904 - Quand j'ai repris mes esprits j'étais tout seul.m4a",""],["Bon. Allons retrouver les autres.","Bien. Vamos a encontrar a los demás.","L09-05 - HF44S10905 - Bon Allons retrouver les autres.m4a",""]]},{"id":"comic-fr-4","code":"HF-44-S1","title":"44th Period","from":10,"to":12,"lines":[["Le groupe D a abandonné Yerim dans le couloir.","El grupo D abandonó a Yerim en el pasillo.","L10-01 - HF44S11001 - Le groupe D a abandonné Yerim dans le couloir.m4a",""],["Qu'est-ce qui s'est passé ? Pourquoi Yerim n'est pas revenue ?","¿Qué pasó? ¿Por qué no volvió Yerim?","L10-02 - HF44S11002 - Qu'est-ce qui s'est passé Pourquoi Yerim n'est pas revenue.m4a",""],["Ah, vous êtes là. Dieu merci, vous allez bien.","Ah, están aquí. Gracias a Dios, están bien.","L10-03 - HF44S11003 - Ah vous êtes là Dieu merci vous allez bien.m4a",""],["Faut le virer !","¡Hay que echarlo!","L10-04 - HF44S11004 - Faut le virer.m4a",""],["Si Yerim revient pas, ça fait de toi un meurtrier.","Si Yerim no vuelve, eso te convierte en un asesino.","L10-05 - HF44S11005 - Si Yerim revient pas ça fait de toi un meurtrier.m4a",""],["On y est allés tous les quatre et on a bien vérifié partout.","Fuimos los cuatro y revisamos bien todo.","L11-01 - HF44S11101 - On y est allés tous les quatre et on a bien vérifié partout.m4a",""],["Calmez-vous, ce n'est pas le moment de vous chamailler.","Cálmense, no es momento de pelearse.","L11-02 - HF44S11102 - Calmez-vous ce n'est pas le moment de vous chamailler.m4a",""],["Lave-toi le visage et sors quand tu auras fini de pleurer.","Lávate la cara y sal cuando termines de llorar.","L11-03 - HF44S11103 - Lave-toi le visage et sors quand tu auras fini de pleurer.m4a",""],["On sera dans le couloir.","Estaremos en el pasillo.","L11-04 - HF44S11104 - On sera dans le couloir.m4a",""],["Ouais ! Je peux y arriver !","¡Sí! ¡Puedo lograrlo!","L11-05 - HF44S11105 - Ouais Je peux y arriver.m4a",""],["Pourquoi tu me regardes comme ça ?","¿Por qué me miras así?","L12-01 - HF44S11201 - Pourquoi tu me regardes comme ça.m4a",""],["Il n'y avait aucun moyen de la ramener.","No había manera de traerla de vuelta.","L12-02 - HF44S11202 - Il n'y avait aucun moyen de la ramener.m4a",""],["Mon oncle n'est qu'un survivant, pas une encyclopédie des phénomènes surnaturels.","Mi tío solo es un superviviente, no una enciclopedia de fenómenos sobrenaturales.","L12-03 - HF44S11203 - Mon oncle n'est qu'un survivant pas une encyclopédie des phénomènes surnaturels.m4a",""],["Après que Yerim soit sortie, on aurait dit que sa voix venait de l'intérieur des toilettes.","Después de que Yerim saliera, parecía que su voz venía del interior de los baños.","L12-04 - HF44S11204 - Après que Yerim soit sortie on aurait dit que sa voix venait de l'intérieur des toilettes.m4a",""],["C'est le mieux que tu peux faire ?","¿Eso es lo mejor que puedes hacer?","L12-05 - HF44S11205 - C'est le mieux que tu peux faire.m4a",""]]},{"id":"comic-fr-5","code":"HF-44-S1","title":"44th Period","from":13,"to":15,"lines":[["La porte est verrouillée.","La puerta está cerrada con llave.","L13-01 - HF44S11301 - La porte est verrouillée.m4a",""],["Pourquoi elle est verrouillée ?","¿Por qué está cerrada con llave?","L13-02 - HF44S11302 - Pourquoi elle est verrouillée.m4a",""],["Ferme-la si tu sais pas de quoi tu parles.","Cállate si no sabes de qué estás hablando.","L13-03 - HF44S11303 - Ferme-la si tu sais pas de quoi tu parles.m4a",""],["On est venus ici pour se disputer ou pour retrouver Yerim ?","¿Vinimos aquí a discutir o a encontrar a Yerim?","L13-04 - HF44S11304 - On est venus ici pour se disputer ou pour retrouver Yerim.m4a",""],["Le plus important, c'est que tout le monde sorte d'ici vivant.","Lo más importante es que todos salgan vivos de aquí.","L13-05 - HF44S11305 - Le plus important c'est que tout le monde sorte d'ici vivant.m4a",""],["Peut-être que les règles qu'on devait suivre partout dans l'école ne s'appliquent plus partout maintenant.","Quizá las reglas que debíamos seguir por todo el instituto ya no se aplican en todas partes.","L14-01 - HF44S11401 - Peut-être que les règles qu'on devait suivre partout dans l'école ne s'appliquent plus par.m4a",""],["On pourrait peut-être explorer.","Tal vez podríamos explorar.","L14-02 - HF44S11402 - On pourrait peut-être explorer.m4a",""],["Si on peut confirmer ça, ça nous enlèverait beaucoup de pression.","Si podemos confirmar eso, nos quitaría mucha presión.","L14-03 - HF44S11403 - Si on peut confirmer ça ça nous enlèverait beaucoup de pression.m4a",""],["Ce dont on avait le plus besoin, c'était le courage de ressortir dehors.","Lo que más necesitábamos era el valor para volver a salir.","L14-04 - HF44S11404 - Ce dont on avait le plus besoin c'était le courage de ressortir dehors.m4a",""],["Il faut qu'on fasse quelque chose si on veut s'échapper.","Tenemos que hacer algo si queremos escapar.","L14-05 - HF44S11405 - Il faut qu'on fasse quelque chose si on veut s'échapper.m4a",""],["Je suis crevée...","Estoy agotada...","L15-01 - HF44S11501 - Je suis crevée.m4a",""],["On va tous crever ici !","¡Todos vamos a morir aquí!","L15-02 - HF44S11502 - On va tous crever ici.m4a",""],["Arrête un peu.","Ya basta.","L15-03 - HF44S11503 - Arrête un peu.m4a",""],["On a déjà fait six expéditions et on ne l'a pas vu.","Ya hicimos seis expediciones y no lo hemos visto.","L15-04 - HF44S11504 - On a déjà fait six expéditions et on ne l'a pas vu.m4a",""],["Il est temps qu'on fasse demi-tour.","Ya es hora de que demos la vuelta.","L15-05 - HF44S11505 - Il est temps qu'on fasse demi-tour.m4a",""]]},{"id":"comic-fr-6","code":"HF-44-S1","title":"44th Period","from":16,"to":18,"lines":[["La visibilité était faible dans le couloir.","La visibilidad era escasa en el pasillo.","L16-01 - HF44S11601 - La visibilité était faible dans le couloir.m4a",""],["On les suit.","Los seguimos.","L16-02 - HF44S11602 - On les suit.m4a",""],["Je vais y retourner.","Voy a volver allí.","L16-03 - HF44S11603 - Je vais y retourner.m4a",""],["Je la connais.","La conozco.","L16-04 - HF44S11604 - Je la connais.m4a",""],["C'est chiant. Reste pas plantée là.","Qué fastidio. No te quedes ahí parada.","L16-05 - HF44S11605 - C'est chiant Reste pas plantée là.m4a",""],["Miji, arrête de pleurer et essaie de te souvenir.","Miji, deja de llorar e intenta recordar.","L17-01 - HF44S11701 - Miji arrête de pleurer et essaie de te souvenir.m4a",""],["On va faire quoi ?","¿Qué vamos a hacer?","L17-02 - HF44S11702 - On va faire quoi.m4a",""],["Je viens de réaliser que j'ai eu un blanc total quand c'est arrivé.","Acabo de darme cuenta de que me quedé completamente en blanco cuando ocurrió.","L17-03 - HF44S11703 - Je viens de réaliser que j'ai eu un blanc total quand c'est arrivé.m4a",""],["On doit tous sortir d'ici.","Todos tenemos que salir de aquí.","L17-04 - HF44S11704 - On doit tous sortir d'ici.m4a",""],["Tu devrais t'en sortir si tu marches.","Deberías lograrlo si caminas.","L17-05 - HF44S11705 - Tu devrais t'en sortir si tu marches.m4a",""],["Qu'est-ce que tu fais ?","¿Qué estás haciendo?","L18-01 - HF44S11801 - Qu'est-ce que tu fais.m4a",""],["Tu sais que c'est interdit de jeter des trucs par terre.","Sabes que está prohibido tirar cosas al suelo.","L18-02 - HF44S11802 - Tu sais que c'est interdit de jeter des trucs par terre.m4a",""],["Ne me parle plus jamais de mourir.","No vuelvas a hablarme de morir.","L18-03 - HF44S11803 - Ne me parle plus jamais de mourir.m4a",""],["Je ne veux pas entendre ces mots.","No quiero oír esas palabras.","L18-04 - HF44S11804 - Je ne veux pas entendre ces mots.m4a",""],["On se détend et on attend que les autres groupes arrivent.","Nos calmamos y esperamos a que lleguen los otros grupos.","L18-05 - HF44S11805 - On se détend et on attend que les autres groupes arrivent.m4a",""]]},{"id":"comic-fr-7","code":"HF-44-S1","title":"44th Period","from":19,"to":21,"lines":[["Tiens ! Merci !","¡Toma! ¡Gracias!","L19-01 - HF44S11901 - Tiens Merci.m4a",""],["C'est pour ça que vous nous avez fait prendre un autre chemin.","Por eso nos hicieron tomar otro camino.","L19-02 - HF44S11902 - C'est pour ça que vous nous avez fait prendre un autre chemin.m4a",""],["Sécurité d'abord.","La seguridad es lo primero.","L19-03 - HF44S11903 - Sécurité d'abord.m4a",""],["On sait comment s'en occuper.","Sabemos cómo encargarnos de eso.","L19-04 - HF44S11904 - On sait comment s'en occuper.m4a",""],["Si vous croisez un monstre, restez calmes.","Si se encuentran con un monstruo, mantengan la calma.","L19-05 - HF44S11905 - Si vous croisez un monstre restez calmes.m4a",""],["Cet endroit n'a pas l'air sûr.","Este lugar no parece seguro.","L20-01 - HF44S12001 - Cet endroit n'a pas l'air sûr.m4a",""],["Vous êtes sûrs que ces dessins viennent des élèves ?","¿Están seguros de que estos dibujos son de los alumnos?","L20-02 - HF44S12002 - Vous êtes sûrs que ces dessins viennent des élèves.m4a",""],["Je vais t'aider.","Voy a ayudarte.","L20-03 - HF44S12003 - Je vais t'aider.m4a",""],["On n'a plus beaucoup de temps.","Ya no nos queda mucho tiempo.","L20-04 - HF44S12004 - On n'a plus beaucoup de temps.m4a",""],["La sonnerie risque de retentir avant qu'on revienne.","La campana podría sonar antes de que volvamos.","L20-05 - HF44S12005 - La sonnerie risque de retentir avant qu'on revienne.m4a",""],["On sera en sécurité tant qu'on reste calmes.","Estaremos a salvo mientras mantengamos la calma.","L21-01 - HF44S12101 - On sera en sécurité tant qu'on reste calmes.m4a",""],["Si vous tombez sur un monstre, rappelez-vous une chose.","Si se encuentran con un monstruo, recuerden una cosa.","L21-02 - HF44S12102 - Si vous tombez sur un monstre rappelez-vous une chose.m4a",""],["Ce monstre attaque même quand on reste immobile.","Este monstruo ataca incluso cuando nos quedamos inmóviles.","L21-03 - HF44S12103 - Ce monstre attaque même quand on reste immobile.m4a",""],["À quoi je sers, moi ?","¿Para qué sirvo yo?","L21-04 - HF44S12104 - À quoi je sers moi.m4a",""],["Éloignons-nous d'abord.","Alejémonos primero.","L21-05 - HF44S12105 - Éloignons-nous d'abord.m4a",""]]},{"id":"comic-fr-8","code":"HF-44-S1","title":"44th Period","from":22,"to":24,"lines":[["Cherchez s'il y a des tenues de rechange !","¡Busquen si hay uniformes de repuesto!","L22-01 - HF44S12201 - Cherchez s'il y a des tenues de rechange.m4a",""],["Je suis délégué de classe. Le leader.","Soy el delegado de la clase. El líder.","L22-02 - HF44S12202 - Je suis délégué de classe Le leader.m4a",""],["Mais c'est ma faute si quelqu'un n'est pas revenu.","Pero es culpa mía si alguien no volvió.","L22-03 - HF44S12203 - Mais c'est ma faute si quelqu'un n'est pas revenu.m4a",""],["On peut encore retrouver Yerim.","Todavía podemos encontrar a Yerim.","L22-04 - HF44S12204 - On peut encore retrouver Yerim.m4a",""],["Je vais les éviter. Toi, trouve comment nous sortir de là.","Yo los esquivaré. Tú encuentra cómo sacarnos de aquí.","L22-05 - HF44S12205 - Je vais les éviter Toi trouve comment nous sortir de là.m4a",""],["Je te jure, j'ai entendu quelque chose là-dedans.","Te juro que oí algo ahí dentro.","L23-01 - HF44S12301 - Je te jure j'ai entendu quelque chose là-dedans.m4a",""],["Pourquoi tu veux encore l'ouvrir ?","¿Por qué quieres abrirla otra vez?","L23-02 - HF44S12302 - Pourquoi tu veux encore l'ouvrir.m4a",""],["On l'a verrouillée pour une bonne raison !","¡La cerramos con llave por una buena razón!","L23-03 - HF44S12303 - On l'a verrouillée pour une bonne raison.m4a",""],["On est de retour.","Hemos vuelto.","L23-04 - HF44S12304 - On est de retour.m4a",""],["Bon retour, les gars.","Bienvenidos de vuelta, chicos.","L23-05 - HF44S12305 - Bon retour les gars.m4a",""],["Si seulement j'avais été un peu plus rapide...","Si tan solo hubiera sido un poco más rápida...","L24-01 - HF44S12401 - Si seulement j'avais été un peu plus rapide.m4a",""],["Pourquoi tu essaies d'aider si c'est pour te faire entraîner aussi ?","¿Por qué intentas ayudar si también vas a quedar atrapada?","L24-02 - HF44S12402 - Pourquoi tu essaies d'aider si c'est pour te faire entraîner aussi.m4a",""],["J'avais une question sur les monstres...","Tenía una pregunta sobre los monstruos...","L24-03 - HF44S12403 - J'avais une question sur les monstres.m4a",""],["Est-ce que chaque monstre n'a qu'une seule règle qui s'applique ?","¿Cada monstruo solo tiene una regla que se aplica?","L24-04 - HF44S12404 - Est-ce que chaque monstre n'a qu'une seule règle qui s'applique.m4a",""],["Regarde le monstre !","¡Mira al monstruo!","L24-05 - HF44S12405 - Regarde le monstre.m4a",""]]},{"id":"comic-fr-9","code":"HF-44-S1","title":"44th Period","from":25,"to":27,"lines":[["Tu as fait une bonne sieste ?","¿Dormiste bien la siesta?","L25-01 - HF44S12501 - Tu as fait une bonne sieste.m4a",""],["Est-ce qu'on peut discuter ?","¿Podemos hablar?","L25-02 - HF44S12502 - Est-ce qu'on peut discuter.m4a",""],["Je sais que c'est vraiment dur pour vous en ce moment.","Sé que ahora mismo esto es realmente difícil para ustedes.","L25-03 - HF44S12503 - Je sais que c'est vraiment dur pour vous en ce moment.m4a",""],["Et si on faisait connaissance pour commencer ?","¿Y si empezamos por conocernos?","L25-04 - HF44S12504 - Et si on faisait connaissance pour commencer.m4a",""],["Maintenant qu'on est ensemble, autant être francs les uns envers les autres.","Ahora que estamos juntos, más vale que seamos sinceros entre nosotros.","L25-05 - HF44S12505 - Maintenant qu'on est ensemble autant être francs les uns envers les autres.m4a",""],["Vous comptez vraiment y aller ?","¿De verdad piensan ir?","L26-01 - HF44S12601 - Vous comptez vraiment y aller.m4a",""],["On ne peut pas rester plantés là éternellement.","No podemos quedarnos ahí parados eternamente.","L26-02 - HF44S12602 - On ne peut pas rester plantés là éternellement.m4a",""],["On s'est fixé trois objectifs pour cette huitième expédition.","Nos fijamos tres objetivos para esta octava expedición.","L26-03 - HF44S12603 - On s'est fixé trois objectifs pour cette huitième expédition.m4a",""],["Chercher des indices sur nos camarades disparus.","Buscar pistas sobre nuestros compañeros desaparecidos.","L26-04 - HF44S12604 - Chercher des indices sur nos camarades disparus.m4a",""],["On devrait vérifier l'endroit où tu as trébuché.","Deberíamos revisar el lugar donde tropezaste.","L26-05 - HF44S12605 - On devrait vérifier l'endroit où tu as trébuché.m4a",""],["Joyeux anniversaire, maman.","Feliz cumpleaños, mamá.","L27-01 - HF44S12701 - Joyeux anniversaire maman.m4a",""],["Le cadeau me touche, mais ce qui m'émeut encore plus, c'est que vous l'ayez préparé tous les deux.","El regalo me conmueve, pero me emociona todavía más que lo hayan preparado los dos.","L27-02 - HF44S12702 - Le cadeau me touche mais ce qui m'émeut encore plus c'est que vous l'ayez préparé tous les.m4a",""],["Alors, vous vous êtes enfin réconciliés ?","Entonces, ¿por fin se reconciliaron?","L27-03 - HF44S12703 - Alors vous vous êtes enfin réconciliés.m4a",""],["Quand quelque chose tombe dans un cercle noir, ce qui est proche des êtres vivants garde sa forme d'origine.","Cuando algo cae en un círculo negro, lo que está cerca de los seres vivos conserva su forma original.","L27-04 - HF44S12704 - Quand quelque chose tombe dans un cercle noir ce qui est proche des êtres vivants garde sa.m4a",""],["Mais ça devrait aller...","Pero debería estar bien...","L27-05 - HF44S12705 - Mais ça devrait aller.m4a",""]]},{"id":"comic-fr-10","code":"HF-44-S1","title":"44th Period","from":28,"to":30,"lines":[["Je me suis réconcilié avec Dohyeon.","Me reconcilié con Dohyeon.","L28-01 - HF44S12801 - Je me suis réconcilié avec Dohyeon.m4a",""],["C'est malpoli de regarder le téléphone des gens sans demander.","Es de mala educación mirar el teléfono de la gente sin pedir permiso.","L28-02 - HF44S12802 - C'est malpoli de regarder le téléphone des gens sans demander.m4a",""],["Pourquoi t'as enregistré ?","¿Por qué lo grabaste?","L28-03 - HF44S12803 - Pourquoi t'as enregistré.m4a",""],["C'est l'occasion parfaite pour t'y mettre aussi !","¡Es la ocasión perfecta para que tú también empieces!","L28-04 - HF44S12804 - C'est l'occasion parfaite pour t'y mettre aussi.m4a",""],["L'odeur de désinfectant est vraiment forte par ici.","El olor a desinfectante es muy fuerte por aquí.","L28-05 - HF44S12805 - L'odeur de désinfectant est vraiment forte par ici.m4a",""],["Qu'est-ce qui t'est arrivé jusqu'à maintenant ?","¿Qué te ha pasado hasta ahora?","L29-01 - HF44S12901 - Qu'est-ce qui t'est arrivé jusqu'à maintenant.m4a",""],["Comment tu t'es retrouvée ici ?","¿Cómo terminaste aquí?","L29-02 - HF44S12902 - Comment tu t'es retrouvée ici.m4a",""],["Les retrouvailles peuvent attendre qu'on sorte d'ici en un seul morceau.","El reencuentro puede esperar hasta que salgamos enteros de aquí.","L29-03 - HF44S12903 - Les retrouvailles peuvent attendre qu'on sorte d'ici en un seul morceau.m4a",""],["Je n'ai pas eu le temps de réfléchir.","No tuve tiempo de pensar.","L29-04 - HF44S12904 - Je n'ai pas eu le temps de réfléchir.m4a",""],["On doit juste passer ce monstre derrière le rideau, et on est libres.","Solo tenemos que pasar este monstruo detrás de la cortina y seremos libres.","L29-05 - HF44S12905 - On doit juste passer ce monstre derrière le rideau et on est libres.m4a",""],["Voilà où on en est pour l'instant.","Así estamos por ahora.","L30-01 - HF44S13001 - Voilà où on en est pour l'instant.m4a",""],["C'est plus simple de vous montrer.","Es más fácil enseñárselo.","L30-02 - HF44S13002 - C'est plus simple de vous montrer.m4a",""],["Nouveau Wongyun à la rescousse !","¡El nuevo Wongyun al rescate!","L30-03 - HF44S13003 - Nouveau Wongyun à la rescousse.m4a",""],["Une fois fermé, on ne peut plus l'ouvrir de l'intérieur !","Una vez cerrada, ¡ya no se puede abrir desde dentro!","L30-04 - HF44S13004 - Une fois fermé on ne peut plus l'ouvrir de l'intérieur.m4a",""],["C'est un foutu labyrinthe ! Pas question que j'entre !","¡Es un maldito laberinto! ¡Ni hablar de que entre!","L30-05 - HF44S13005 - C'est un foutu labyrinthe Pas question que j'entre.m4a",""]]},{"id":"comic-fr-11","code":"HF-44-S1","title":"44th Period","from":31,"to":33,"lines":[["Voilà pourquoi rester dans la classe n'est pas la meilleure solution.","Por eso quedarse en el aula no es la mejor solución.","L31-01 - HF44S13101 - Voilà pourquoi rester dans la classe n'est pas la meilleure solution.m4a",""],["On dirait que les escaliers ont gonflé.","Parece que las escaleras se han hinchado.","L31-02 - HF44S13102 - On dirait que les escaliers ont gonflé.m4a",""],["L'école est en train de se transformer.","El instituto se está transformando.","L31-03 - HF44S13103 - L'école est en train de se transformer.m4a",""],["Reviens tout de suite.","Vuelve ahora mismo.","L31-04 - HF44S13104 - Reviens tout de suite.m4a",""],["Les autres vont s'inquiéter. Faut y aller.","Los demás se van a preocupar. Tenemos que irnos.","L31-05 - HF44S13105 - Les autres vont s'inquiéter Faut y aller.m4a",""],["Fini ! Ça tremble.","¡Basta! Está temblando.","L32-01 - HF44S13201 - Fini Ça tremble.m4a",""],["Selon Dohyeon, le labyrinthe n'a pas de sortie.","Según Dohyeon, el laberinto no tiene salida.","L32-02 - HF44S13202 - Selon Dohyeon le labyrinthe n'a pas de sortie.m4a",""],["Il faut que je trouve une solution !","¡Tengo que encontrar una solución!","L32-03 - HF44S13203 - Il faut que je trouve une solution.m4a",""],["Une corde suffira pour nous en sortir !","¡Una cuerda bastará para sacarnos de aquí!","L32-04 - HF44S13204 - Une corde suffira pour nous en sortir.m4a",""],["Les gars, rassemblez des couvertures et des oreillers. Vite !","Chicos, junten mantas y almohadas. ¡Rápido!","L32-05 - HF44S13205 - Les gars rassemblez des couvertures et des oreillers Vite.m4a",""],["Seojeong, t'es où ?","Seojeong, ¿dónde estás?","L33-01 - HF44S13301 - Seojeong t'es où.m4a",""],["Cinq minutes. Ça fait déjà...","Cinco minutos. Ya han pasado...","L33-02 - HF44S13302 - Cinq minutes Ça fait déjà.m4a",""],["Cette infirmière-monstre est bien condamnée à rester dans le labyrinthe, n'est-ce pas ?","Esta enfermera monstruo está condenada a quedarse en el laberinto, ¿verdad?","L33-03 - HF44S13303 - Cette infirmière-monstre est bien condamnée à rester dans le labyrinthe n'est-ce pas.m4a",""],["Le seul moyen qu'elle sorte, c'est qu'on soit malades.","La única forma de que salga es que estemos enfermos.","L33-04 - HF44S13304 - Le seul moyen qu'elle sorte c'est qu'on soit malades.m4a",""],["Les murs alentour commençaient à gonfler et à fondre.","Las paredes de alrededor empezaban a hincharse y derretirse.","L33-05 - HF44S13305 - Les murs alentour commençaient à gonfler et à fondre.m4a",""]]},{"id":"comic-fr-12","code":"HF-CRITICAL-S1","title":"Critical Hit","from":1,"to":4,"lines":[["Le corps humain est vraiment difficile à satisfaire.","El cuerpo humano es realmente difícil de satisfacer.","L01-01 - HFCritS10101 - Le corps humain est vraiment difficile à satisfaire.m4a",""],["Comme si on était destiné à une forme ou une autre de gêne moche.","Como si estuviéramos destinados a alguna forma de incomodidad horrible.","L01-02 - HFCritS10102 - Comme si on était destiné à une forme ou une autre de gêne moche.m4a",""],["Je ne ressens absolument rien.","No siento absolutamente nada.","L01-03 - HFCritS10103 - Je ne ressens absolument rien.m4a",""],["Maintenant il ne reste plus que moi et le vide de mon existence.","Ahora solo quedamos yo y el vacío de mi existencia.","L01-04 - HFCritS10104 - Maintenant il ne reste plus que moi et le vide de mon existence.m4a",""],["Malheureusement, votre colis n'a pas pu être livré.","Desafortunadamente, su paquete no pudo ser entregado.","L02-01 - HFCritS10201 - Malheureusement votre colis n'a pas pu être livré.m4a",""],["Veuillez vous rendre en relais colis ou faites-vous livrer un autre jour.","Diríjase a un punto de entrega o haga que se lo entreguen otro día.","L02-02 - HFCritS10202 - Veuillez vous rendre en relais colis ou faites-vous livrer un autre jour.m4a",""],["Non, j'y crois pas, pas encore !","¡No, no me lo puedo creer, otra vez no!","L02-03 - HFCritS10203 - Non j'y crois pas pas encore.m4a",""],["Cette fois-ci, je ne me ferai pas avoir.","Esta vez no dejaré que me engañen.","L02-04 - HFCritS10204 - Cette fois-ci je ne me ferai pas avoir.m4a",""],["J'ai une relation particulière avec le sommeil.","Tengo una relación particular con el sueño.","L03-01 - HFCritS10301 - J'ai une relation particulière avec le sommeil.m4a",""],["C'est une pure addiction, j'en ai jamais assez.","Es una pura adicción; nunca tengo suficiente.","L03-02 - HFCritS10302 - C'est une pure addiction j'en ai jamais assez.m4a",""],["Cet homme commence le travail à 4 h 00.","Este hombre empieza a trabajar a las cuatro de la mañana.","L03-03 - HFCritS10303 - Cet homme commence le travail à 4 h 00.m4a",""],["Je peux me préparer en quinze minutes.","Puedo prepararme en quince minutos.","L03-04 - HFCritS10304 - Je peux me préparer en quinze minutes.m4a",""],["Depuis quelques jours, mon ascenseur est en panne.","Desde hace unos días, mi ascensor está averiado.","L04-01 - HFCritS10401 - Depuis quelques jours mon ascenseur est en panne.m4a",""],["Je vis au dernier étage d'un vieil immeuble et les réparations sont compliquées.","Vivo en el último piso de un edificio viejo y las reparaciones son complicadas.","L04-02 - HFCritS10402 - Je vis au dernier étage d'un vieil immeuble et les réparations sont compliquées.m4a",""],["La montée est à des années-lumière de la descente.","Subir está a años luz de bajar.","L04-03 - HFCritS10403 - La montée est à des années-lumière de la descente.m4a",""],["J'ai fait la rencontre de mes voisins.","Conocí a mis vecinos.","L04-04 - HFCritS10404 - J'ai fait la rencontre de mes voisins.m4a",""]]},{"id":"manga-fr-1","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":2,"to":4,"lines":[["Vous avez fait tomber cette…","Se le ha caído esto…","",""],["Quelle belle Tomayto.","Qué hermosa Tomayto.","",""],["Tu es toute seule, ma petite ?","¿Estás sola, pequeña?","",""],["Ah oui, merci !","Ah, sí, ¡gracias!","",""],["Mais il s'est fait mal au dos.","Pero se lastimó la espalda.","",""],["D'habitude, c'est mon papy qui y va.","Normalmente va mi abuelo.","",""],["Je vais à une foire qu'on peut pas se permettre de rater.","Voy a una feria que no podemos permitirnos perder.","",""],["Du coup, c'est moi qui y vais à sa place.","Así que voy yo en su lugar.","",""],["C'est une compétition pour déterminer quel est le meilleur produit, là.","Es una competencia para decidir cuál es el mejor producto.","",""],["Si vous gagnez, vot' produit gagnera une réputation, c'qui fait qu'vous aurez plus de commandes.","Si ganan, su producto se hará famoso y recibirán más pedidos.","",""],["Et plus de commandes, ça veut dire…","Y más pedidos significa…","",""],["Qu’est-ce que tu feras, si tu deviens riche ?","¿Qué harás si te haces rica?","",""],["Je m'achèterai un drone pour vaporiser des pesticides, un beau tracteur tout neuf…","Me compraré un dron para fumigar pesticidas y un bonito tractor nuevo…","",""],["Et une serre tunnel entièrement automatisée, avec régulateur de température.","Y un invernadero túnel totalmente automatizado, con regulador de temperatura.","",""]],"level":"B1"},{"id":"manga-fr-2","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":4,"to":6,"lines":[["Gagner le jackpot !!","¡Ganar el premio gordo!","",""],["Oh, c'est bien, ça.","Oh, eso está bien.","",""],["Et puis, je me prendrai un chien gros comme ça, et…","Y también me compraré un perro así de grande y…","",""],["Et puis, je voudrais vivre dans une giga baraque !","¡Y también me gustaría vivir en una mansión enorme!","",""],["Je me trouverai un mari de rêve…","Me encontraré un marido de ensueño…","",""],["Ça fait beaucoup !!","¡Son muchas cosas!","",""],["Et je veux neuf enfants !","¡Y quiero nueve hijos!","",""],["Désolé de vous interrompre.","Disculpe que la interrumpa.","",""],["Je peux passer, s'il vous plaît, madame ?","¿Puedo pasar, por favor, señora?","",""],["Oh, pardon. Je vous fais de la place.","Oh, perdón. Le hago sitio.","",""],["Magne-toi, la vioque !!","¡Apúrate, vieja!","",""],["… Oh ? Ma ceinture…","…¿Eh? Mi cinturón…","",""],["Ça marche comment, ces bidules, déjà ?","¿Cómo funcionaban estos cacharros?","",""],["Désolée. Vous allez au petit coin ?","Disculpe. ¿Va al baño?","",""]],"level":"A2"},{"id":"manga-fr-3","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":7,"to":13,"lines":[["Qu'est-ce que vous faites ?","¿Qué está haciendo?","",""],["Faut pas frapper les dames âgées.","No se golpea a las señoras mayores.","",""],["À cause des roulis, je me suis endormi.","Con tanto traqueteo, me quedé dormido.","",""],["Au beau milieu d'une grosse mission.","En plena misión importante.","",""],["Quelle prestation médiocre.","Qué actuación tan mediocre.","",""],["L'excellence ressemblerait plus à ça.","La excelencia se parecería más a esto.","",""],["Je supporte pas les élèves qui font ça !","¡No soporto a los alumnos que hacen eso!","",""],["Tu regardes encore le ciel par la fenêtre !","¡Otra vez mirando el cielo por la ventana!","",""],["Okay ! Si un avion décolle à 700 km par heure…","¡Bien! Si un avión despega a 700 km por hora…","",""],["C'est parce que tu n'écoutais pas !","¡Es porque no estabas escuchando!","",""],["Donc, euh, le point fixe…","Entonces, eh, el punto fijo…","",""],["Et, euh, l'angle… C'est…","Y, eh, el ángulo… es…","",""],["Pff, les cours, ça sert à rien.","Pff, las clases no sirven para nada.","",""],["Qu'elle est bête, maître Turbo-pare-chocs.","Qué tonta es, maestra Turbo-Parachoques.","",""]],"level":"A2"},{"id":"manga-fr-4","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":13,"to":15,"lines":[["Haha… Vous, vous comprenez.","Jaja… usted sí entiende.","",""],["Vous êtes d'accord avec moi, vous, pas vrai ?","Está de acuerdo conmigo, ¿verdad?","",""],["Étudier ces trucs, ça donne rien de bon dans nos jours.","Estudiar estas cosas no sirve de mucho hoy en día.","",""],["Les angles, les probas…","Los ángulos, las probabilidades…","",""],["Pardon. Je suis pressée.","Perdón. Tengo prisa.","",""],["Je me demande si le Young Sunday de la semaine est déjà sorti.","Me pregunto si ya salió el Young Sunday de esta semana.","",""],["Qu'est-ce qui te fait courir comme ça ?","¿Por qué corres así?","",""],["On va te mettre bien.","Te vamos a hacer pasarla bien.","",""],["Je pense que passer du bon temps avec nous sera une expérience bien plus intéressante.","Creo que pasar un buen rato con nosotros será una experiencia mucho más interesante.","",""],["C'est la seule certitude qu'on puisse avoir, pas vrai ?","Es la única certeza que podemos tener, ¿verdad?","",""],["Il est sérieux.","Va en serio.","",""],["De toute évidence, elle a des ennuis !","Es evidente que está en problemas.","",""],["Il me faut des renforts dès que possible.","Necesito refuerzos cuanto antes.","",""],["Altercation en cours. Une fille se fait harceler.","Hay un altercado. Están acosando a una chica.","",""]],"level":"B1"},{"id":"manga-fr-5","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":15,"to":20,"lines":[["Azuma, t'es dans le coin ?","Azuma, ¿andas por aquí?","",""],["Je suis déjà sur place !!","¡¡Ya estoy en el lugar!!","",""],["Il veut quoi, tête de noeud ??","¿Qué quiere este idiota?","",""],["C'est qui que tu traites de racailles ?!!!","¡¿A quién llamas basura?!","",""],["Bien joué, Azuma. T’es le héros de cette ville…!","Bien hecho, Azuma. Eres el héroe de esta ciudad…","",""],["Je vais… M’amuser…","Voy a… divertirme…","",""],["Avec la petite !!!","¡¡Con la pequeña!!","",""],["Azuma ? T’es allé trop loin…!","¿Azuma? ¡Te pasaste…!","",""],["Hum… Je peux au moins savoir votre nom…?","Hum… ¿al menos puedo saber sus nombres…?","",""],["C'est rien. Je n'ai fait que ce que je pouvais.","No es nada. Solo hice lo que pude.","",""],["J'ai un entretien important aujourd'hui…","Hoy tengo una entrevista importante…","",""],["Merci infiniment, Azuma.","Muchas gracias, Azuma.","",""],["On est partenaires.","Somos compañeros.","",""],["Moi, c'est Azuma Higashi !","Yo soy Azuma Higashi.","",""]],"level":"A2"},{"id":"manga-fr-6","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":20,"to":109,"lines":[["Et lui, c’est Tokio Kurohara !","¡Y él es Tokio Kurohara!","",""],["Tu crois qu’il est allé à l’hôpital ?","¿Crees que fue al hospital?","",""],["Et demander à mon père si je peux faire quelque chose pour aider.","Y preguntarle a mi padre si puedo hacer algo para ayudar.","",""],["Je pense que je vais rentrer à la maison.","Creo que voy a volver a casa.","",""],["Peut-être… Que c’est pas qu’ils aiment ça ou non… Tu vois ?","Tal vez… no es que les guste o no… ¿entiendes?","",""],["C’est censé être un élève au lycée Tsuru.","Se supone que es alumno del instituto Tsuru.","",""],["Il est premier de sa classe et son père est un haut gradé dans la police.","Es el primero de su clase y su padre es un alto mando de la policía.","",""],["Si j’étais aussi flinguée de la tête que toi, je tomberais en morceaux.","Si estuviera tan mal de la cabeza como tú, me desmoronaría.","",""],["Tout Azuma qu’il est, il est allé trop loin, ce soir.","Por muy Azuma que sea, esta noche se pasó de la raya.","",""],["Ma sœur dit que je devrais tenir ta main, pour te ressembler un peu plus.","Mi hermana dice que debería tomarte de la mano para parecerme un poco más a ti.","",""],["Elle a dit que si on se tenait par la main, tu déteindrais sur moi.","Ella dijo que, si fuéramos de la mano, se me pegaría algo de ti.","",""],["Tu peux encore courir, non ? Je suis sûr que tu peux…","Aún puedes correr, ¿no? Estoy seguro de que puedes…","",""],["C’est ma sœur qui le dit…","Eso lo dice mi hermana…","",""],["Merci pour tout ! À plus, les gars…!","¡Gracias por todo! ¡Nos vemos, chicos…!","",""]],"level":"B1"},{"id":"manga-fr-7","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":139,"to":203,"lines":[["Arrête de squatter la salle de bain ! Je me lève tôt, moi, demain !","¡Deja de acaparar el baño! ¡Mañana yo me levanto temprano!","",""],["Et tu as pris un sacré coup !","¡Y recibiste un golpe tremendo!","",""],["On est à 20 minutes à pied de l’hôpital.","Estamos a veinte minutos a pie del hospital.","",""],["Faut que je pense à autre cho- se pendant un temps. Ça fait trop peur…","Tengo que pensar en otra cosa por un rato. Da demasiado miedo…","",""],["Ils se sont occupés de moi à l’hôpital, et j’ai fait un bilan sanguin rapide.","Se ocuparon de mí en el hospital y me hicieron un análisis de sangre rápido.","",""],["À vos yeux, je suis même déjà mort.","A sus ojos, ya estoy muerto.","",""],["Si je peux lui ressembler, même un tout petit peu…","Si puedo parecerme a él, aunque sea un poquito…","",""],["Ils ont fermé il y a un mois…","Lo cerraron hace un mes…","",""],["Je suis dans un zoo fermé avec une fille…","Estoy en un zoológico cerrado con una chica…","",""],["Je suis presque certain que c’est le même vautour…","Estoy casi seguro de que es el mismo buitre…","",""],["Non ! Il est pas mort !","¡No! ¡No está muerto!","",""],["Et il y as utilisé tes pouvoirs, pas vrai ? Tu étais du côté du troisième district à Oba","Y usaste tus poderes allí, ¿verdad? Estabas por el tercer distrito de Oba.","",""],["Pour tester si tu étais bien un choujin. J’ai donc émis mon propre signal.","Para comprobar si de verdad eras un choujin, emití mi propia señal.","",""],["Tu veux bien prendre ça au sérieux ?","¿Quieres tomarte esto en serio?","",""]],"level":"B1"},{"id":"manga-fr-8","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":212,"to":340,"lines":[["Ils ont des génisses et tout ça, là ?!","¡¿Tienen vaquillas y todo eso ahí?!","",""],["C’est que je suis un peu empoisonné, Radio néné…","Es que estoy un poco envenenado, Radio Nené…","",""],["Tu es plus lent parce que tu t’es pété le bras !","¡Eres más lento porque te rompiste el brazo!","",""],["Et, euhhhh, en fait, quand il y a trois personnes du coup…","Y, eeeh, o sea, cuando hay tres personas, pues…","",""],["J’ai un ami qui m’a raconté cette histoire à propos de trois flé- ches…","Tengo un amigo que me contó una historia sobre tres flechas…","",""],["Tu t’es métamorphosé, non ? Où est ton identi- fication ?","Te transformaste, ¿no? ¿Dónde está tu identificación?","",""],["C’est qui, cette armoire à glace ? Un choujin…??","¿Quién es ese grandulón? ¿Un choujin…??","",""],["Moi aussi, je suis un choujin.","Yo también soy un choujin.","",""],["À présent, la ville fait au plus vite pour capturer les animaux qui se sont échappés.","Por ahora, la ciudad trabaja a toda prisa para capturar a los animales que escaparon.","",""],["Nous sommes au début de la troisième manche et c’est au tour du lycée Tsuru d’attaquer.","Estamos al comienzo de la tercera entrada y es el turno del instituto Tsuru de atacar.","",""],["De même, il est au lycée Tsuru, comme toi.","Además, está en el instituto Tsuru, como tú.","",""],["Je suis dans la classe a.","Estoy en la clase A.","",""],["Je vais peut-être viser la classe a, moi.","Tal vez yo apunte a la clase A.","",""],["C’est aussi ici qu’il a été reçu en classe a ?","¿También aquí fue aceptado en la clase A?","",""]],"level":"B1"},{"id":"manga-fr-9","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":348,"to":477,"lines":[["Ils sont à l’intérieur. Je vais te les enfu- mer, moi.","Están adentro. Yo te los voy a sacar con humo.","",""],["Ils peuvent faire vraiment peur quand on est en retard sur les paie- ments.","Pueden dar mucho miedo cuando uno se atrasa con los pagos.","",""],["Vous êtes dans la mê- me école que notre grand frère…?","¿Están en la misma escuela que nuestro hermano mayor…?","",""],["Vous savez où il est…?","¿Saben dónde está…?","",""],["Le seul choix qui s’offre à nous, c’est de nous occuper de lui ici et maintenant !","¡La única opción que tenemos es ocuparnos de él aquí y ahora!","",""],["Le truc où Kagomura s’est plus ou moins suicidé…","La cosa con la que Kagomura más o menos se suicidó…","",""],["C’est à peine si tu pourrais faire un échauffement potable pour moi.","Apenas me servirías de calentamiento decente.","",""],["Et là, on pourra jouer à la balle si tu veux.","Y entonces podremos jugar a la pelota si quieres.","",""],["À compter de ce jour, Tokio, tu es un choujin…","A partir de hoy, Tokio, eres un choujin…","",""],["Alors en fait, hier, j’ai vu Nishigahara à la gare !","Entonces, de hecho, ¡ayer vi a Nishigahara en la estación!","",""],["Et… Un, deux, trois, quatre…","Y… uno, dos, tres, cuatro…","",""],["Et elle travaille d’arrache-pied pour parvenir à son but de venir en aide aux gens.","y trabaja sin descanso para lograr su objetivo de ayudar a la gente.","",""],["Il y a une fille qui s’est transfor-mée en choujin à peu près à la même période que moi,","Hay una chica que se transformó en choujin más o menos en la misma época que yo,","",""],["Et je me suis dit qu’elle pouvait possible-ment être une choujin, elle aussi.","Y pensé que ella también posiblemente podía ser una choujin.","",""]],"level":"B1"},{"id":"manga-fr-10","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":478,"to":573,"lines":[["Mais j’ai pas la moindre idée de ce à quoi ça ressem-blerait, là, tout de suite…","Pero no tengo ni la menor idea de cómo se vería, así, de repente…","",""],["Quand un chien détecte une piste, on place un marqueur sur la carte.","Cuando un perro detecta un rastro, colocamos un marcador en el mapa.","",""],["Que là où les chiens sont regroupés, ça nous indique que c’est là où la cible est active.","Que donde se agrupan los perros nos indica dónde está activa la presa.","",""],["J’ai pété un câble et la situation m’a échappé, c’est tout !","Perdí los estribos y la situación se me fue de las manos, ¡eso es todo!","",""],["Alors, Seiko, c’est ta prime qui est en jeu… Tu vas y arriver !","Vamos, Seiko, tu recompensa está en juego… ¡lo lograrás!","",""],["Elle peut discerner si quelqu’un dit la vérité ou non, en voyant un x ou un o.","Puede discernir si alguien dice la verdad o no viendo una X o una O.","",""],["Donc je me dis que je devrais peut-être faire quelque chose, moi aussi.","Así que me digo que quizá yo también debería hacer algo.","",""],["Je vais peut-être au moins faire un peu d’exercice en rentrant à la maison...","Al menos quizá haga un poco de ejercicio al volver a casa…","",""],["Je t’assure que nous allons faire tout ce qui est en notre pouvoir.","Te aseguro que haremos todo lo que esté en nuestro poder.","",""],["J’ai la fâcheuse tendance à fourrer mon nez un peu partout.","Tengo la mala costumbre de meter las narices en todas partes.","",""],["En plus, qui voudrait partager une pizza avec un gars qui a une pomme comme la mienne.","Además, ¿quién querría compartir una pizza con un tipo con una cara como la mía?","",""],["Il a l’air sympa... Qu’est-ce que je raconte ? Il est flippant...","Parece simpático… ¿qué estoy diciendo? Da miedo…","",""],["Ils sont dans un motel à Minami City. Le nom c’est le o’Neill.","Están en un motel de Minami City. Se llama O’Neill.","",""],["Je n’en attendais pas moins de toi et Ricardo. J’aimerais aller le voir immédiatement.","No esperaba menos de ti y Ricardo. Me gustaría ir a verlo de inmediato.","",""]],"level":"B1+"},{"id":"manga-fr-11","kind":"manga","source":"Choujin X","code":"manga-French-Choujin X","title":"Choujin X","from":593,"to":794,"lines":[["Tu es certain d’être ici pour le sauver ?","¿Estás seguro de estar aquí para salvarlo?","",""],["Si je me souviens bien, tu m’as porté un coup au visage.","Si recuerdo bien, me golpeaste en la cara.","",""],["Dotés de la forme et du pouvoir qui leur conviennent le mieux.","Dotados de la forma y el poder que mejor les convienen.","",""],["Tu participes à la ligue de football du collège et au tournoi de basket de la préfecture ?","¿Participas en la liga de fútbol de secundaria y en el torneo de básquet de la prefectura?","",""],["Quant à elle, la fille, qui savait ce que sa mère avait fait, se dit :","En cuanto a la niña, que sabía lo que había hecho su madre, se dijo:","",""],["On va à la piscine, et on va regar-der un feu d’artifice.","Vamos a la piscina y a ver fuegos artificiales.","",""],["Et c’est à ce moment-là que l’autre incapé est venu nous rentrer dedans.","Y fue entonces cuando el otro inútil vino a chocarse contra nosotros.","",""],["Je vois. Et moi qui espérais vous inviter à une chasse à la bête... Dans ce cas...","Ya veo. Y yo que esperaba invitarlo a una cacería de la bestia… en ese caso…","",""],["Je suis bien soulagé que vous vous parliez maintenant, avec Ely.","Me siento muy aliviado de que ahora se hablen, tú y Ely.","",""],["À mon frère cadet, qui nous a quittés.","A mi hermano menor, que nos dejó.","",""]],"level":"B1+"},{"id":"manga-fr-12","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":3,"to":5,"lines":[["Je me souviens du temps de mon enfance.","Recuerdo la época de mi infancia.","",""],["Elle était la lance.","Ella era la lanza.","",""],["Et ma mère.","Y mi madre.","",""],["Tante helnr avait aimé ma mère, l’avait adorée quand elle était enfant.","La tía helnr había querido a mi madre, la había adorado cuando era niña.","",""],["Ce n’est pas par ambition égoïste qu’elle défiait sa sœur aînée pour le contrôle de notre peuple.","No era por ambición egoísta por lo que desafiaba a su hermana mayor para hacerse con el control de nuestro pueblo.","",""],["Petite sœur, si tu veux me prendre la tribu... Tu vas devoir faire mieux que ça !","Hermanita, si quieres arrebatarme la tribu... ¡vas a tener que hacerlo mejor que eso!","",""],["On les avait entendues se disputer la nuit précédente.","Las habían oído discutir la noche anterior.","",""],["Je ne prête pas l’oreille aux couards, ma sœur. Tu veux te méfier ? Que tes armes affrontent les miennes.","No presto oídos a los cobardes, hermana. ¿quieres desconfiar? Que tus armas se enfrenten a las mías.","",""],["Tu ne mérites pas ton rang, grena. Nous devrions planter des semences. Nous devrions pêcher les anguilles d’été...","No mereces tu rango, grena. Deberíamos plantar semillas. Deberíamos pescar las anguilas de verano...","",""],["Mais ma mère ne la laissait pas parler.","Pero mi madre no la dejaba hablar.","",""],["Comprends cela, ma sœur.","Entiende esto, hermana mía.","",""],["Je suis la lance et la hache...","Soy la lanza y el hacha...","",""],["...je suis le blizzard et l’éclair...","...soy la ventisca y el rayo...","",""],["...je suis grena !","...¡soy grena!","",""]],"level":"B1"},{"id":"manga-fr-13","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":5,"to":7,"lines":[["Et ce n’est pas toi que le destin a choisi.","Y no es a ti a quien ha elegido el destino.","",""],["Ma tante a survécu, peut-être parce que ma mère et ses liés-par-le-sang étaient toujours prompts à fêter leurs victoires.","Mi tía sobrevivió, quizá porque mi madre y quienes estaban unidos a ella por la sangre siempre se apresuraban a celebrar sus victorias.","",""],["Maalcrom, comment va-t-elle ?","Maalcrom, ¿cómo está ella?","",""],["Ashe, tu dois dire à ta mère de...","Ashe, tienes que decirle a tu madre que...","",""],["C’est décidé. Demain, nous attaquons les enfants des glaces. Nous prendrons à cette tribu ce dont nous avons besoin pour l’hiver.","Está decidido. Mañana atacaremos a los Hijos de los Hielos. Le quitaremos a esta tribu lo que necesitamos para el invierno.","",""],["C’était la mauvaise période de l’année et nos pertes récentes nous avaient affaiblis, mais nous allions repartir en guerre.","Era una mala época del año y nuestras pérdidas recientes nos habían debilitado, pero volveríamos a la guerra.","",""],["En dominant ma tante, ma mère s’était assurée que seul son plan, seule sa vérité seraient évoqués.","Al imponerse sobre mi tía, mi madre se había asegurado de que solo se hablara de su plan y de su verdad.","",""],["J’aurais aimé croire en cette vérité.","Me habría gustado creer en esa verdad.","",""],["Mais je n’étais pas si bête.","Pero yo no era tan idiota.","",""],["Maman, tu as mangé aujourd'hui ?","Mamá, ¿has comido hoy?","",""],["Les repaires stellaires correspondent à ces ruines. Tu te souviens ? Ceux qu'on a pris au clan des crocs brisés ?","Los refugios estelares coinciden con estas ruinas. ¿te acuerdas? ¿los que le quitamos al clan de los colmillos rotos?","",""],["Tu fais de nouveau des cartes.","Estás haciendo mapas otra vez.","",""],["Oui. On y est presque. Cette fois... Cette fois, j'en suis sûre.","Sí. Ya casi lo conseguimos. Esta vez... Esta vez, estoy segura.","",""],["Le trône d'avarosa.","El trono de avarosa.","",""]],"level":"B1"},{"id":"manga-fr-14","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":7,"to":8,"lines":[["Le trône d'avarosa, le hall et le trésor de la grande déesse.","El trono de avarosa, el salón y el tesoro de la gran diosa.","",""],["Un mythe ancien, que les prêtres du givre disaient pure légende. Un conte pour les enfants et pour les fous.","Un mito antiguo que los sacerdotes de la escarcha decían que era pura leyenda. Un cuento para los niños y para los locos.","",""],["Pourquoi tante helrin t'a-t-elle défiée ?","¿por qué te desafió la tía helrin?","",""],["Maman, tu as mangé aujourd'hui ?","Mamá, ¿has comido hoy?","",""],["J’ai gagné. Le reste ne compte pas.","He ganado. Lo demás no importa.","",""],["Ça compte. Ton obsession envers le mythe du trône d’avarosa... Elle est de nouveau hors de contrôle...","Sí importa. Tu obsesión con el mito del trono de avarosa... Vuelve a estar fuera de control...","",""],["Notre tribu est pauvre, ashe. C’est ainsi que nous lui rendrons sa grandeur. C’est sa destinée.","Nuestra tribu es pobre, ashe. Así es como le devolveremos su grandeza. Ese es su destino.","",""],["Destinée. J’exécrais ce mot. Il exerçait un terrible pouvoir sur ma mère.","Destino. Aborrecía esa palabra. Ejercía un poder terrible sobre mi madre.","",""],["Tu ne dors pas et tu ne manges pas, n’est-ce pas ?","No duermes ni comes, ¿verdad?","",""],["Il la plongeait dans une folie dont je ne pouvais la protéger.","La sumía en una locura de la que yo no podía protegerla.","",""],["Une frénésie hallucinée, aussi brutale et irraisonnée que sa volonté.","Un frenesí delirante, tan brutal e irracional como su voluntad.","",""],["S’il te plaît, maman... Fais une pause. Je vais te préparer un ragoût, ou...","Por favor, mamá... Descansa un poco. Voy a prepararte un guiso o...","",""],["Comment se passe ton entraînement ? Ma fille est-elle enfin digne d’être appelée une sublimée ?","¿cómo va tu entrenamiento? ¿por fin es mi hija digna de ser llamada hija del hielo?","",""],["Je... Je suis prête.","Yo... Estoy lista.","",""]],"level":"B1"},{"id":"manga-fr-15","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":9,"to":14,"lines":[["Voyons ça. Choisis une arme, dévoile ta force.","Veamos. Elige un arma, revela tu fuerza.","",""],["Le moindre éclat de glace pure entraîne la mort. Seul un sublimé entraîné peut espérer toucher ces armes et y survivre.","El más mínimo fragmento de hielo puro causa la muerte. Solo un sublimado entrenado puede aspirar a tocar estas armas y sobrevivir a ello.","",""],["Et même pour les sublimés, même avec la protection de la garde, la glace pure envahit le corps.","E incluso en los sublimados, aun con la protección de la guarda, el hielo puro invade el cuerpo.","",""],["Je me souviens de la prière de lissandra que m'a apprise maalcrom :","Recuerdo la plegaria de lissandra que me enseñó maalcrom:","",""],["Laquelle veux-tu, ma fille ?","¿cuál quieres, hija mía?","",""],["« La glace n'est pas douleur... »","«El hielo no es dolor...»","",""],["« Elle est abandon. »","«Es abandono.»","",""],["Je suis fière de toi. Très fière.","Estoy orgullosa de ti. Muy orgullosa.","",""],["Tu n’as pas à rougir, ma fille. Essayer cela si jeune...","No tienes de qué avergonzarte, hija mía. Intentar eso siendo tan joven...","",""],["Ce n’est pas la destinée de ta cousine. C’est la tienne.","Ese no es el destino de tu prima. Es el tuyo.","",""],["Je suis sa fierté. Ma mère est sa déesse.","Soy su orgullo. Mi madre es su diosa.","",""],["Il existe un vieux dicton. « Ne prends pas pied sur la glace qui se fendille déjà. »","Hay un viejo dicho: «No pongas el pie sobre el hielo que ya se está resquebrajando».","",""],["Mère, tu les as fait marcher pendant trois jours sans repos.","Madre, los has hecho marchar durante tres días sin descanso.","",""],["Un éclaireur a dû nous repérer.","Un explorador debió de vernos.","",""]],"level":"B1"},{"id":"manga-fr-16","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":15,"to":32,"lines":[["Tout ce dont nous avons besoin pour survivre à l’hiver est ici !","¡Todo lo que necesitamos para sobrevivir al invierno está aquí!","",""],["Pas pour les vivres ou la vengeance… À cause d’un conte pour enfant !","¡No por provisiones ni por venganza… sino por un cuento infantil!","",""],["Mère ! Non !","¡Madre! ¡No!","",""],["Pourquoi était-ce soudain si important pour moi ?","¿Por qué de pronto era tan importante para mí?","",""],["Nous avons encore marché six jours.","Caminamos seis días más.","",""],["…mais je ne pouvais pas l’abandonner. Pas quand elle avait besoin de moi.","…pero no podía abandonarla. No cuando me necesitaba.","",""],["Combien de nuits ma mère a-t-elle passées à consulter ses cartes ?","¿Cuántas noches ha pasado mi madre consultando sus mapas?","",""],["Il ne nous reste plus de bois ?","¿Ya no nos queda leña?","",""],["Juste assez pour une nuit. Tiens, mange ça. Puis essaie de dormir.","Solo queda para una noche. Toma, come esto. Luego intenta dormir.","",""],["Non, cette fois, j’y suis. Ashe, cette fois… Je…","No, esta vez sí lo tengo. Ashe, esta vez… yo…","",""],["C’était la première fois que je donnais un ordre…","Era la primera vez que daba una orden…","",""],["Mère, je peux gagner assez de temps pour que tu traverses…","Madre, puedo ganar tiempo suficiente para que cruces…","",""],["Non, Ashe, même si ton courage m’honore…","No, Ashe, aunque tu valor me honra…","",""],["Sachez-le… Je suis la chef de guerre des avarosaans.","Que lo sepan… soy la jefa de guerra de los Avarosanos.","",""]],"level":"B1"},{"id":"manga-fr-17","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":33,"to":55,"lines":[["Elle peut encore y arriver ! Laisse-lui un peu de temps !","¡Aún puede lograrlo! ¡Dale un poco de tiempo!","",""],["Ma mère est morte les yeux ouverts.","Mi madre murió con los ojos abiertos.","",""],["Je n’ai jamais vu un prêtre du givre aussi fort.","Nunca había visto a un sacerdote del hielo tan fuerte.","",""],["Non. Je dois honorer la quête de ma mère.","No. Debo honrar la búsqueda de mi madre.","",""],["J’ignore combien de temps j’ai marché. Mais…","Ignoro cuánto tiempo caminé. Pero…","",""],["Tu deviendras un grand chef de guerre.","Te convertirás en una gran jefa de guerra.","",""],["…c’était sans importance. La carte de ma mère se finissait au-dessus d’une falaise.","…no importaba. El mapa de mi madre terminaba sobre un precipicio.","",""],["Tu as trahi la tribu ?","¿Traicionaste a la tribu?","",""],["Je connaissais mon destin. Comme je sais que je dois tenir parole et finir…","Conocía mi destino. Como sé que debo cumplir mi palabra y acabar…","",""],["Tu espérais te lier à moi par serment et finir dans mon lit ?","¿Esperabas unirte a mí por juramento y terminar en mi cama?","",""],["Dors. Dors, mon amour. Même le souvenir de la quête de ta mère doit mourir.","Duerme. Duerme, mi amor. Incluso el recuerdo de la búsqueda de tu madre debe morir.","",""],["…grâce à la détermination que ma mère m’avait transmise.","…gracias a la determinación que mi madre me había transmitido.","",""],["Je suis partie sur la mer de glace, sachant que ma tribu était morte.","Partí por el mar de hielo, sabiendo que mi tribu estaba muerta.","",""],["Il y aurait à manger au bout de la piste.","Habría comida al final del rastro.","",""]],"level":"B1+"},{"id":"manga-fr-18","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":55,"to":67,"lines":[["Mais même un enfant sait qu’un repas trop facile est en fait…","Pero hasta un niño sabe que una comida demasiado fácil en realidad es…","",""],["Elle combattait avec une rage qui aurait pu faire pâlir ma mère.","Luchaba con una rabia que habría podido hacer palidecer a mi madre.","",""],["Ensemble, nous avons vaincu la bête…","Juntas, vencimos a la bestia…","",""],["Je suis affamée. Je ne cherchais pas à insulter ta tribu, ursidée.","Estoy hambrienta. No buscaba insultar a tu tribu, Ursidé.","",""],["J’ai dû faire un effort immense pour ne pas hurler.","Tuve que hacer un esfuerzo inmenso para no gritar.","",""],["La glace pure de l’arc s’emparait de mon bras.","El hielo puro del arco se apoderaba de mi brazo.","",""],["Cinq étés. Tous les ans, je guettais ta venue.","Cinco veranos. Todos los años, aguardaba tu llegada.","",""],["C’est bon de te voir, mon amie.","Qué bueno verte, amiga mía.","",""],["Plus que tout, pendant ces cinq étés, j’avais peur de ne plus jamais te revoir.","Más que nada, durante esos cinco veranos, temía no volver a verte jamás.","",""],["Pourquoi es-tu seule sur la mer de glace ? Où est ta famille, Ashe ?","¿Por qué estás sola en el mar de hielo? ¿Dónde está tu familia, Ashe?","",""],["Comment peuvent-ils être aussi rapides ?","¿Cómo pueden ser tan rápidos?","",""],["Je ne sais pas, mais ils ne traversent pas l’eau, dieux merci.","No lo sé, pero no cruzan el agua, gracias a los dioses.","",""],["Ils écartent les forts du pouvoir.","Apartan a los fuertes del poder.","",""],["Qu’est-il arrivé à ta grand-mère ?","¿Qué le pasó a tu abuela?","",""]],"level":"B1"},{"id":"manga-fr-19","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":67,"to":72,"lines":[["Tu es bien la seule à le penser. Cinq étés. Tu m’as tellement manquée, Ashe.","Eres la única que piensa eso. Cinco veranos. Te he extrañado tanto, Ashe.","",""],["Désolée. Je sais ce qu’elle a représenté pour toi, après le départ de ta mère.","Lo siento. Sé lo que ella representó para ti después de la partida de tu madre.","",""],["Tu as brisé sa mâchoire !?","¿Le rompiste la mandíbula?","",""],["Quand nous serons à terre, il faudra donner les vivres au plus vite.","Cuando lleguemos a tierra, habrá que entregar las provisiones cuanto antes.","",""],["Elle m’a aidée à tuer un grellefen. Et je rapporte du poisson et du loup de mer.","Me ayudó a matar a un grellefen. Y traigo pescado y lobo marino.","",""],["Essaie de donner la nourriture, Ashe. Je vais te gagner du temps.","Intenta entregar la comida, Ashe. Voy a ganar tiempo para ti.","",""],["Qui est l’étrangère que tu as amenée dans ma tribu ?","¿Quién es la extranjera que trajiste a mi tribu?","",""],["Et où as-tu trouvé ce butin ?","¿Y dónde encontraste ese botín?","",""],["Et un prêtre du givre sait si l’on ment.","Y un sacerdote del hielo sabe si alguien miente.","",""],["Il est interdit à toutes les tribus de chasser sur les terres des oubliés.","Está prohibido que todas las tribus cacen en las tierras de los Olvidados.","",""],["Je n’offre un abri qu’en échange de la vérité. Quel est ton nom, étrangère ?","Solo ofrezco refugio a cambio de la verdad. ¿Cuál es tu nombre, extranjera?","",""],["Où avez-vous trouvé ces vivres ?","¿Dónde encontraron estas provisiones?","",""],["Durant mon enfance, nul n’a jamais dit un mot contre la mère de Sejuani. C’était interdit.","Durante mi infancia, nadie dijo jamás una palabra contra la madre de Sejuani. Estaba prohibido.","",""],["Elle a combattu avec courage. La moitié de la viande lui est due.","Luchó con valentía. Le corresponde la mitad de la carne.","",""]],"level":"B1+"},{"id":"manga-fr-20","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":72,"to":83,"lines":[["En pleine mer. Un grellefen a attaqué mon navire. Sejuani m’a sauvée.","En alta mar. Un grellefen atacó mi barco. Sejuani me salvó.","",""],["Sans moi, il n’y aurait rien à manger, mère.","Sin mí, no habría nada que comer, madre.","",""],["Tu ne décides pas avec qui nous partageons, ma fille.","No decides con quién compartimos, hija mía.","",""],["Nous devrions… Euh… Décharger la nourriture du bateau. Je l’offre en gage de bonne foi.","Deberíamos… eh… descargar la comida del barco. La ofrezco como prueba de buena fe.","",""],["Patience. Il n’y en a pas assez. Quand la faim viendra…","Paciencia. No hay suficiente. Cuando llegue el hambre…","",""],["C’est mon amie. Je connais Ashe. Quand grand-mère et sa mère travaillaient ensemble…","Es mi amiga. Conozco a Ashe. Cuando mi abuela y su madre trabajaban juntas…","",""],["Et tu n’es rien de plus qu’une proie pour Urkata et ses frères.","Y no eres más que una presa para Urkata y sus hermanos.","",""],["Moi, au moins, je te protégerai.","Yo, al menos, te protegeré.","",""],["Votre loyauté suffit amplement à nous payer.","Su lealtad basta de sobra para pagarnos.","",""],["J’ai mon amie. La fille de Grena.","Tengo a mi amiga. La hija de Grena.","",""],["Mais là, c’est différent… Je peux le faire.","Pero ahora es diferente… Puedo hacerlo.","",""],["L’avarosan avec qui je suis revenue à la tribu. C’est la fille sublimée de Grena.","La avarosana con la que regresé a la tribu. Es la hija Sublimada de Grena.","",""],["Svaag. À part ta cervelle, rien n’est plus petit que ton épée.","Svaag. Aparte de tu cerebro, nada es más pequeño que tu espada.","",""],["La fille de Grena. Oui, Maalcrom nous a beaucoup parlé de toi.","La hija de Grena. Sí, Maalcrom nos habló mucho de ti.","",""]],"level":"B1+"},{"id":"manga-fr-21","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":83,"to":96,"lines":[["Quel est ton nom, avarosan ?","¿Cuál es tu nombre, avarosana?","",""],["Demain matin, je déciderai quoi faire de cette…","Mañana por la mañana decidiré qué hacer con esta…","",""],["Sejuani, tu as trop d’audace. Comme toujours.","Sejuani, tienes demasiada osadía. Como siempre.","",""],["Tu Vas défier ta mère pour prendre le contrôle de la tribu ?","¿Vas a desafiar a tu madre para tomar el control de la tribu?","",""],["Alors je dois repartir. Retourner à la mer de glace…","Entonces debo irme. Volver al Mar de Hielo…","",""],["Tu es de mon sang, Sejuani, de la griffe hivernale. Tu es ma sœur d’armes.","Eres de mi sangre, Sejuani, de la Garra Invernal. Eres mi hermana de armas.","",""],["Il faut faire vite, la lune monte, fille de Grena.","Hay que darse prisa, la luna sube, hija de Grena.","",""],["Il est temps de mourir.","Es hora de morir.","",""],["Ma tribu meurt de faim, Ashe. Tu es ma sœur d’armes. C’est un ordre.","Mi tribu muere de hambre, Ashe. Eres mi hermana de armas. Es una orden.","",""],["Tu comptes donc défier ta propre mère pour la tribu ?","Entonces, ¿piensas desafiar a tu propia madre por la tribu?","",""],["Tu es une sublimée ! Et tu n’as survécu que parce que le destin t’a menée à moi.","¡Eres una Sublimada! Y solo sobreviviste porque el destino te llevó hasta mí.","",""],["Et je fais exactement ce que ta mère aurait fait.","Y hago exactamente lo que habría hecho tu madre.","",""],["Ils mourront pour que ma tribu vive. Et pour que tu puisses la rejoindre.","Morirán para que mi tribu viva. Y para que puedas unirte a ella.","",""],["Elle a pris dix Prétariens pour te protéger. Elle t’a entraînée. Elle a cru en toi.","Se llevó a diez Prétariens para protegerte. Te entrenó. Creyó en ti.","",""]],"level":"B1"},{"id":"manga-fr-22","kind":"manga","source":"Ashe","code":"manga-French-Ashe","title":"Ashe","from":96,"to":100,"lines":[["Je dirais que ta mère a élevé une sotte.","Diría que tu madre crió a una tonta.","",""],["Pour être un chef, il faut savoir mentir, voler et sacrifier.","Para ser líder, hay que saber mentir, robar y sacrificar.","",""],["Tu as fait de moi ta sœur d’armes. Comment dois-je honorer cela ?","Me hiciste tu hermana de armas. ¿Cómo debo honrar eso?","",""],["Tu peux les regarder mourir de faim ? Ou tu peux rester à mes côtés comme ma sœur.","¿Puedes verlos morir de hambre? O puedes quedarte a mi lado como mi hermana.","",""],["Tu seras toujours ma sœur, Sejuani ! Jamais tu ne seras mon ennemie.","¡Siempre serás mi hermana, Sejuani! Jamás serás mi enemiga.","",""],["Jamais je n’avais été aussi seule, la première fois que j’ai arpenté la mer de glace.","Nunca había estado tan sola como la primera vez que recorrí el Mar de Hielo.","",""],["Mais quand Sejuani a disparu dans la brume, j’ai compris…","Pero cuando Sejuani desapareció en la niebla, comprendí…","",""],["Je suis Ashe. Fille de Grena. Je suis l’arc.","Soy Ashe. Hija de Grena. Soy el arco.","",""],["Merci pour votre pitié, sublimée. Je suis Gjura Axehan de la tribu des Ebrataal.","Gracias por tu piedad, Sublimada. Soy Gjura Axehan de la tribu de los Ebrataal.","",""],["Préparez le snekkja. Nous partons à midi.","Preparen el snekkja. Partimos al mediodía.","",""]],"level":"B1+"}];
